impl<B, S> Default for PathRouter<S, B> {
    fn default() -> Self {
        Self {
            routes: Default::default(),
            node: Default::default(),
            prev_route_id: RouteId(0),
            matched_path_by_id: HashMap::new(),
            nest_tail_route_ids: HashMap::new(),
            ignored_param_prefixes: vec![Arc::from(NEST_TAIL_PARAM), Arc::from(FALLBACK_PARAM)],
            decode_path_params: true,
            nested_prefixes: Vec::new(),
            capture_original_uri: true,
        }
    }
}

impl<S, B> fmt::Debug for PathRouter<S, B> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("PathRouter")
            .field("routes", &self.routes)
            .field("node", &self.node)
            .finish()
    }
}

impl<S, B> Clone for PathRouter<S, B> {
    fn clone(&self) -> Self {
        Self {
            routes: self.routes.clone(),
            node: self.node.clone(),
            prev_route_id: self.prev_route_id,
            matched_path_by_id: self.matched_path_by_id.clone(),
            nest_tail_route_ids: self.nest_tail_route_ids.clone(),
            ignored_param_prefixes: self.ignored_param_prefixes.clone(),
            decode_path_params: self.decode_path_params,
            nested_prefixes: self.nested_prefixes.clone(),
            capture_original_uri: self.capture_original_uri,
        }
    }
}

/// Wrapper around `matchit::Router` that supports merging two `Router`s.
#[derive(Clone, Default)]
struct Node {
    inner: matchit::Router<RouteId>,
    route_id_to_path: HashMap<RouteId, Arc<str>>,
    path_to_route_id: HashMap<Arc<str>, RouteId>,
}

impl Node {
    fn insert(
        &mut self,
        path: impl Into<String>,
        val: RouteId,
    ) -> Result<(), matchit::InsertError> {
        let path = path.into();

        self.inner.insert(&path, val)?;

        let shared_path: Arc<str> = path.into();
        self.route_id_to_path.insert(val, shared_path.clone());
        self.path_to_route_id.insert(shared_path, val);

        Ok(())
    }

    fn at<'n, 'p>(
        &'n self,
        path: &'p str,
    ) -> Result<matchit::Match<'n, 'p, &'n RouteId>, MatchError> {
        self.inner.at(path)
    }
}

impl fmt::Debug for Node {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Node")
            .field("paths", &self.route_id_to_path)
            .finish()
    }
}

