}

pub(crate) fn path_for_nested_route<'a>(prefix: &'a str, path: &'a str) -> Cow<'a, str> {
    PathRouter::<(), Body>::join_nested_path(prefix, path)
}

pub(super) fn rewrite_nested_uri(uri: &Uri, prefix: &str) -> Option<Uri> {
    PathRouter::<(), Body>::strip_prefix_with_query(uri, prefix)
}

